struct vector3d
{
  float x, y, z;
};

extern const vector3d ZEROVEC;

class stringx
{
public:
  stringx(const char *, int = -1);
  ~stringx();
};

struct po
{
  char pad[48];
  vector3d position;
};

class entity
{
public:
  char pad0[80];
  po *abs_po;
  char pad1[72];
  int cull;

  const vector3d &get_abs_position() const { return abs_po->position; }
  void SetCull(bool value) { cull = value; }
};

class conglomerate : public entity
{
public:
  entity *get_member(const stringx &);
};

enum WaveRegionEnum
{
  WAVE_REGION_DUMMY
};

class SurfBoardObjectClass
{
public:
  vector3d wave_current;
  vector3d wave_normal;
  char pad0[72];
  WaveRegionEnum wave_region;
  char pad1[788];

  vector3d GetWaveNormal() { return wave_normal; }
  WaveRegionEnum GetWaveRegion() { return wave_region; }
  vector3d GetWaveCurrent() { return wave_current; }
};

class ScoringManager
{
public:
  void FinishChain(bool);
};

enum
{
  STATE_WIPEOUT_GENERAL = 84,
  SUPER_STATE_WIPEOUT = 3,
  WIP_PHYS_TUMBLE = 4,
  BOARD_ANIM_NULL = -1
};

class kellyslater_controller
{
public:
  char pad0[12];
  entity *owner;
  char pad1[32];
  int state;
  char pad2[4];
  int super_state;
  char pad3[3396];
  SurfBoardObjectClass my_board_controller;
  ScoringManager my_scoreManager;
  char pad4[2047];
  bool wave_hint_valid;
  char pad5[143];
  vector3d surfer_velocity;
  vector3d wip_position;
  vector3d water_current;
  vector3d water_normal;
  WaveRegionEnum water_region;
  int wip_phys_state;
  int wipeout_type;
  float low_wip_y_height;
  int get_on_board_anim;
  int b_get_on_board_anim;
  int num_wipeouts;
  bool no_buttons_pressed;
  char pad6[7];
  int wip_anim_dis;
  int wip_anim_free;
  int wip_anim_imp;
  int wip_anim_imp2;
  int wip_anim_trans;
  int wip_anim_swim;
  int b_wip_anim_dis;
  int b_wip_anim_free;
  int b_wip_anim_imp;
  int goofy_int;
  bool dry;
  char pad7[87];
  float tween_timer;
  float tween_time;

  entity *get_owner() { return owner; }
  bool IsAIPlayer();
  void InitKlugeWipeout(int tumble_anim, int swim_anim);
};

void kellyslater_controller::InitKlugeWipeout(int tumble_anim, int swim_anim)
{
	my_scoreManager.FinishChain(true);
	surfer_velocity = ZEROVEC;
	wip_position = ((conglomerate *)get_owner())->get_member("BIP01 PELVIS")->get_abs_position();
	low_wip_y_height = wip_position.y - 1.5f;

	state = STATE_WIPEOUT_GENERAL;
	super_state = SUPER_STATE_WIPEOUT;

	wip_anim_trans = tumble_anim;
	wip_anim_swim = swim_anim;
	b_wip_anim_dis = BOARD_ANIM_NULL;

	tween_timer = 0.0f;
	tween_time = 0.3f;

	water_normal = my_board_controller.GetWaveNormal();

	wip_phys_state = WIP_PHYS_TUMBLE;
	dry = false;
	wave_hint_valid = false;
	water_region = (WaveRegionEnum) my_board_controller.GetWaveRegion();
	water_current = my_board_controller.GetWaveCurrent();

	if (!IsAIPlayer())
		get_owner()->SetCull(false);
}
